SELECT n.name, mi1.info, MIN(non_leaf_1398.t_production_year), MAX(non_leaf_1398.t_production_year)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, non_leaf_1398
WHERE (mi1.info IN ('Argentina:13','Canada:13+','Canada:14A','Finland:K-18','Germany:12','Iceland:L','Netherlands:AL','New Zealand:R16','Singapore:ADV','South Korea:15','South Korea:All','UK:PG','USA:E10+','USA:TV-Y','USA:TV-Y7')) AND (it1.id IN ('5')) AND n.id = non_leaf_1398.ci_person_id AND (n.name ILIKE '%lor%') AND (kt.kind IN ('tv series','video game','video movie')) AND (rt.role IN ('actor','actress','composer','costume designer'));